#[derive(Debug)]
enum DateTime64 {
    Nat,
    Valid(u64),
}

fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    x.iter().map(|date_time| match date_time {
        DateTime64::Nat => true,
        DateTime64::Valid(_) => false,
    }).collect()
}

